#include <stdio.h>
int main(void){int state=1600,rate=1024,capacity=state-rate,lane=64,rate_lanes=rate/lane,cap_lanes=capacity/lane;printf("SHA-3 state=%d bits, rate/block=%d bits, capacity=%d bits\n",state,rate,capacity);printf("Each lane is %d bits: rate occupies %d lanes, capacity occupies %d lanes.\n",lane,rate_lanes,cap_lanes);puts("Initially all capacity lanes are zero. XORing a message block affects the rate portion, not the capacity portion.");puts("Under the instruction to ignore the permutation and track the original zero lanes, the capacity lanes remain zero forever; they will not all become nonzero after any finite number of blocks.");puts("In actual SHA-3, the Keccak-f permutation mixes state lanes between rounds; ignoring it removes the diffusion mechanism.");return 0;}
